                    case (2 << 3) | 1:  // Access, field 2, fixed64
                        value.Access = (global::ProtoBuf.Reflection.Access)(checked((int)unchecked((long)state.ReadRawFixed64())));
                        break;
                    default:
                        if (state.IsScopeEnd(tag)) return value;
                        if (IsKnownField(tag)) state.ThrowUnexpectedWireType(tag);
                        state.AppendExtensionData(tag, value);
                        break;
                }
                tag = state.ReadRawTag();
            }
            return value;

            static bool IsKnownField(uint tag) => (tag >> 3) is 1 or 2;
        }
    }
}
